                if p is not None:
                    return p
            for k in ("self", "agent"):
                p = pos(v.get(k))
                if p is not None:
                    return p
        elif isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return [int(v[0]), int(v[1])]
